package com.phonebackup.local;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.net.Uri;import android.provider.OpenableColumns;import android.view.*;import android.widget.*;
import java.io.*;import java.net.*;import java.security.*;import java.util.*;import org.json.*;
public class MainActivity extends Activity {
 EditText host;TextView status;ArrayList<Uri> selected=new ArrayList<>();final int PICK=9;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);host=new EditText(this);host.setHint("Windows computer IP address");l.addView(host);Button choose=new Button(this);choose.setText("Select photos, videos and documents");l.addView(choose);choose.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK);});Button start=new Button(this);start.setText("Backup Now");l.addView(start);status=new TextView(this);l.addView(status);setContentView(l);start.setOnClickListener(v->new Thread(this::send).start());}
 protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==PICK&&res==RESULT_OK&&data!=null){if(data.getClipData()!=null){for(int j=0;j<data.getClipData().getItemCount();j++)selected.add(data.getClipData().getItemAt(j).getUri());}else if(data.getData()!=null)selected.add(data.getData());status.setText(selected.size()+" files selected");}}
 String name(Uri uri){try(Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0)return c.getString(i);}}return "file";}
 byte[] read(Uri uri)throws Exception{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(java.util.Locale.US,"%02x",b&255));return s.toString();}
 void send(){try{ArrayList<byte[]> blobs=new ArrayList<>();JSONArray files=new JSONArray();for(Uri u:selected){byte[] b=read(u);blobs.add(b);JSONObject j=new JSONObject();j.put("name",name(u));j.put("category","files");j.put("size",b.length);j.put("sha256",hex(MessageDigest.getInstance("SHA-256").digest(b)));files.put(j);}JSONObject meta=new JSONObject();meta.put("device",Build.MODEL);meta.put("files",files);byte[] head=meta.toString().getBytes("UTF-8");try(Socket sock=new Socket()){sock.connect(new InetSocketAddress(host.getText().toString().trim(),38471),10000);DataOutputStream out=new DataOutputStream(sock.getOutputStream());out.writeInt(head.length);out.write(head);for(byte[] b:blobs)out.write(b);out.flush();}runOnUiThread(()->status.setText("Sent "+blobs.size()+" files. Check Windows verification report."));}catch(Exception e){runOnUiThread(()->status.setText("Backup failed: "+e.getMessage()));}}
}
